"""Build a private, source-linked cover comparison, not a new book edition."""
from pathlib import Path
from urllib.request import Request,urlopen
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime,timezone,timedelta
import io,json,base64,html
from PIL import Image
D=Path(__file__).resolve().parent;R=D.parents[2]
books=[
{'id':'controlled','title':'Trustworthy Online Controlled Experiments','page':'https://experimentguide.com/','format_page':'https://www.cambridge.org/core/books/trustworthy-online-controlled-experiments/D97B26382EB0EB2DC2019A7A7B518F59','image':'https://experimentguide.com/wp-content/uploads/2019/11/2019-11-Cover-198x300.gif','format_evidence':'Cambridge商品本文でDigital形式を直接確認。表紙画像は著者公式サイト。','observation':'専門主題を大きく、A/B Testingを副題で具体化。ハイポの中心像は比喩で、図解パネルではない。','takeaway':'主題の可読性と比喩の一本化。権威やキャラクターは借用しない。'},
{'id':'lean','title':'Lean Analytics','page':'https://leananalyticsbook.com/','format_page':'https://www.overdrive.com/media/1256262/lean-analytics','image':'https://leananalyticsbook.com/wp-content/uploads/2016/03/book-cover-full.png','format_evidence':'著者サイトの表紙を直接確認。電子書籍掲載は検索で確認、O’ReillyとOverDriveの本文はアクセス制限。','observation':'大きいLEAN ANALYTICSと、使って何をするかを示す副題。説明図は使わず文字で強くする。','takeaway':'表紙に図を増やすより主題と読者利益を優先する。'},
{'id':'story','title':'Storytelling with Data','page':'https://www.storytellingwithdata.com/books','format_page':'https://books.google.com/books/about/Storytelling_with_Data.html?id=retRCgAAQBAJ','image':'https://books.google.com/books/publisher/content?id=retRCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl','format_evidence':'著者の本紹介とGoogle Booksの書誌・提供表紙を直接確認。Google Books当該画面は利用可能eBookなしと表示し、同画面での販売は確認していない。','observation':'白地と青い題字。データの断片が脇へ退き、題名が中心になる。','takeaway':'本文のグラフをそのまま表紙に持ち込まず、必要な印象だけ残す。'},
{'id':'testing','title':'Testing Business Ideas','page':'https://www.strategyzer.com/library/testing-business-ideas-book','format_page':'https://catalogimages.wiley.com/images/db/pdf/9781119551447.excerpt.pdf','image':'https://cdn.prod.website-files.com/64830736e7f43d491d70ef30/64bfca43998875181ce0bdc1_64a57f82d532feda71463af9_649ec04c4cae62095c21ced3_BOOK_COVER_WEB_03-Testing_Business_Ideas.webp','format_evidence':'Strategyzer公式紹介と表紙モックアップを直接確認。ePDF/ePubは公式抜粋の検索表示に記載、OverDrive本文は403。','observation':'太い題名と大きい一つの象徴。実験器具、観察、アイデアを一つの絵にまとめる。','takeaway':'詳しいステップ表ではなく、一つの中心像で方法の性格を伝える。'},
{'id':'literacy','title':'데이터 문해력','page':'https://ebook-product.kyobobook.co.kr/dig/epd/ebook/E000003158108','format_page':'https://ebook-product.kyobobook.co.kr/dig/epd/ebook/E000003158108','image':'https://contents.kyobobook.co.kr/sih/fit-in/458x0/pdt/9788965402916.jpg','format_evidence':'교보 전자책 상품의 표지와 PDF 형식을 직접 확인.','observation':'핵심어 데이터 문해력이 가장 크다. 보조문구와 삽화가 많지만 주제어의 우선순위는 선명하다.','takeaway':'무조건 요소를 없애는 것이 아니라, 가장 먼저 읽힐 말을 고른다.'}
]
# English/Japanese notes below are replaced with Korean editorial notes for delivery.
ko={
'controlled':('출판사 Cambridge의 Digital 형식을 직접 확인했다. 표지는 저자 공식 사이트에서 확인했다.','전문 주제를 크게 쓰고 A/B Testing을 부제로 구체화한다. 중앙 하마는 하나의 비유이며 설명용 패널이 아니다.','주제의 가독성과 중심 비유만 참고한다. 캐릭터나 저자의 권위는 가져오지 않는다.'),
'lean':('저자 사이트의 표지를 직접 확인했다. 전자책 목록은 검색으로 확인했으나 O’Reilly와 OverDrive 본문은 접근 제한이다.','큰 LEAN ANALYTICS와 사용 목적을 말하는 부제. 설명 그림 없이 문자만으로 주제를 강하게 전달한다.','설명 그림을 늘리기보다 주제와 독자에게 주는 약속을 먼저 세운다.'),
'story':('저자 소개와 Google Books 서지 및 제공 표지를 직접 확인했다. 해당 Google Books 화면은 이용 가능한 eBook 없음으로 표시하므로 그곳의 판매를 확인했다고 말하지 않는다.','흰 바탕과 파란 제목이 중심이다. 데이터 조각은 가장자리로 물러나 주제를 보조한다.','본문 그래프를 그대로 옮기기보다 책의 성격을 보여 주는 최소 요소를 남긴다.'),
'testing':('Strategyzer 공식 소개와 표지 목업을 직접 확인했다. 공식 발췌의 검색 표시에는 ePDF와 ePub이 있으나 OverDrive 본문은 403이다.','굵은 제목과 하나의 큰 상징이 중심이다. 실험, 관찰과 아이디어를 한 이미지로 묶는다.','여러 설명 카드보다 하나의 대표 비유를 택할 수 있다. 제공 이미지는 실물 표지 목업이다.')}
for b in books:
 if b['id'] in ko:b['format_evidence'],b['observation'],b['takeaway']=ko[b['id']]
def fetch(b):
 req=Request(b['image'],headers={'User-Agent':'Mozilla/5.0'})
 with urlopen(req,timeout=40) as response:data=response.read();status=response.status
 im=Image.open(io.BytesIO(data));im.seek(0);b['original_pixels']=list(im.size);im=im.convert('RGBA');im.thumbnail((360,540));out=D/('reference_'+b['id']+'.png');im.save(out);b['image_file']=out.name;b['http_status']=status
 return b
with ThreadPoolExecutor(max_workers=5) as pool:books=list(pool.map(fetch,books))
assert len(books)==5 and len({b['id'] for b in books})==5
own=R/'e-book/design/v18/review/cover.png';assert own.is_file()
def datauri(p):return 'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode()
E=html.escape
cards=''
for b in books:
 cards+=f'<article class="reference"><div class="image"><img src="{datauri(D/b["image_file"])}" alt="{E(b["title"])} 실제 공개 표지"></div><h3>{E(b["title"])}</h3><p>{E(b["observation"])}</p><p class="takeaway">적용 원칙: {E(b["takeaway"])}</p><a href="{E(b["page"])}" target="_blank" rel="noopener">표지 출처</a></article>'
cards+=f'<article class="reference ours"><div class="image"><img src="{datauri(own)}" alt="현재 v0.18 검토용 표지"></div><h3>현재 v0.18</h3><p>질문은 크게 읽히지만 A/B 테스트와 TRI-V는 작다. 아래 안내 카드의 설명은 축소하면 읽기 어렵다.</p><p class="takeaway">가장 먼저 보이는 것은 캠페인 운영 질문이지 A/B 실험서의 주제가 아니다.</p></article>'
titles=[('권장 / 범위와 주제 우선','CRM A/B 테스트,\n결과에서 결정까지','TRI-V로 비교를 점검하고 적용 대상과 다음 행동을 정하는 법','검색 주제와 책의 끝 산출물이 명확하다. 다만 표현의 개성과 짧은 호기심은 상대적으로 약하다.'),('대안 / 질문의 친근함 유지','A/B 테스트,\n이 결과로 결정해도 될까요?','CRM 실무자를 위한 TRI-V 판단 방법론','현 가제의 말투를 살리면서 주제어를 제목에 넣는다. 길이가 늘어 타이포그래피 조정이 필요하다.'),('대안 / 방법론 중심','TRI-V로 읽는\nCRM A/B 테스트','비교의 근거에서 적용 범위와 다음 행동까지','방법론이 전면에 선다. 처음 보는 독자에게는 TRI-V가 무엇인지 설명할 부담이 가장 크다.')]
titlecards=''.join(f'<article class="title-option"><small>{E(label)}</small><h3>{E(t).replace(chr(10),"<br>")}</h3><p>{E(sub)}</p><p class="tradeoff">{E(trade)}</p></article>' for label,t,sub,trade in titles)
page=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>표지와 제목 비판적 비교 | TRI-V 검토</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#F5F1E8;color:#142D32;font-family:"Malgun Gothic",Arial,sans-serif;line-height:1.65}}main{{max-width:1440px;padding:36px;margin:auto}}h1{{font-size:32px;line-height:1.3;margin:8px 0 20px}}h2{{font-size:23px;margin:32px 0 12px}}h3{{line-height:1.4}}.label,small{{color:#125E59;font-weight:bold}}.lede{{max-width:1020px}}.scope{{font-size:14px;color:#4F625F}}.references{{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px}}.reference{{padding:14px;background:white;border:1px solid #BAC9C1}}.image{{height:250px;display:flex;align-items:flex-start;justify-content:center}}.image img{{width:160px;height:232px;object-fit:contain;object-position:center top}}.reference h3{{font-size:16px;min-height:48px}}.reference p{{font-size:14px}}.reference a{{color:#125E59;display:inline-flex;align-items:center;min-height:44px}}a:focus-visible{{outline:3px solid #125E59;outline-offset:3px}}.ours{{outline:2px solid #125E59}}.takeaway{{border-top:1px solid #BAC9C1;padding-top:12px}}.judgment{{background:white;padding:20px 24px}}.judgment strong{{color:#8D4029}}.title-options{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}}.title-option{{padding:24px;background:white;border-top:4px solid #125E59}}.title-option h3{{font-size:25px}}.tradeoff{{color:#4F625F;font-size:14px}}table{{border-collapse:collapse;width:100%;background:white}}td,th{{padding:14px;text-align:left;vertical-align:top;border-bottom:1px solid #BAC9C1}}th{{background:#E3EEE8}}footer{{margin-top:28px;font-size:13px;color:#4F625F}}@media(max-width:1100px){{.references{{grid-template-columns:repeat(3,minmax(0,1fr))}}}}@media(max-width:650px){{main{{padding:20px}}.references{{grid-template-columns:repeat(2,minmax(0,1fr))}}.title-options{{grid-template-columns:1fr}}h1{{font-size:27px}}.reference{{padding:8px}}.image img{{max-width:100%}}td,th{{padding:9px;font-size:14px}}}}
</style><main><div class="label">COVER & POSITIONING / 검토 전용</div><h1>예뻐졌는가보다,<br>무슨 책인지 먼저 읽히는가</h1><p class="lede">전자책으로 검색하거나 유통 형식을 확인한 실무서의 공개 표지를 비교했다. 판매 순위 조사나 책 전체 실독 비교가 아니며, 전자책 전용 표지가 종이책과 반드시 다르다고 가정하지 않는다. 디자인을 모사하지 않고 정보 위계와 제목의 약속을 비교한다.</p><p class="scope">이미지 영역 폭은 160px다. 목업과 판형의 차이는 유지했으며 실제 구매 반응을 시험한 결과가 아니다. 외부 표지는 비평용 참고이며 새 책의 본문이나 판매 파일에 포함하지 않는다.</p><section class="references">{cards}</section><h2>현 가제에 대한 판단</h2><section class="judgment"><p><strong>그대로 확정하는 것은 권하지 않는다.</strong> “그래서, 이 캠페인 계속할까요?”는 말투는 친근하지만 캠페인 전략, 문구 제작, 운영 중단 판단서로도 읽힐 수 있다. 이 책은 실험 설계부터 증거의 해석, 고객군의 적용 범위와 다음 행동을 다룬다.</p><p>“그래서,”가 큰 한 줄을 차지하는 반면 주제어 A/B 테스트는 작은 분류 문구에 있다. 본문 사례를 설명하는 두 카드는 강의 자료에는 유용하지만, 작은 표지에서 책의 정체성을 대신하기 어렵다. TRI-V를 핵심으로 두되 처음 보는 약어를 제목의 유일한 약속으로 삼지는 않는다.</p></section><h2>제목 후보 / 아직 본책에 반영하지 않은 제안</h2><section class="title-options">{titlecards}</section><h2>우선 수정 세 가지</h2><table><thead><tr><th>우선</th><th>전 → 제안</th><th>이유</th></tr></thead><tbody><tr><td>주제어</td><td>상단 작은 A/B 분류 → 큰 제목에 CRM A/B 테스트</td><td>질문의 분위기보다 어떤 책인지 먼저 식별하게 한다.</td></tr><tr><td>대표 이미지</td><td>작은 안내 설명 카드 두 개 → 하나의 대표 비유 또는 타이포그래피 중심</td><td>읽어야 하는 설명을 줄이고 비교와 판단이라는 인상을 남긴다.</td></tr><tr><td>방법론</td><td>하단의 작은 TRI-V와 저자 설명 → 제목 아래 독자 작업을 설명하는 TRI-V 부제</td><td>방법론의 존재와 쓰임을 함께 보이되 효용이 입증됐다는 표현은 쓰지 않는다.</td></tr></tbody></table><footer>색은 기존 편집용 제안 팔레트 #142D32, #125E59, #4F625F, #8D4029를 사용한다. 기존 대비 계산에서 흰 배경 위 네 글자색 모두 본문 AA를 통과했다. 후보는 편집 제안이며 사람의 최종 승인 전이다. 페르소나별 전권 비평은 별도 파일로 정리한다.</footer></main></html>'''
(D/'BENCHMARK.html').write_text(page,encoding='utf-8',newline='\n')
metadata={'checked_at_seoul':datetime.now(timezone(timedelta(hours=9))).isoformat(),'scope':'Cover appearance and title positioning, not sales rankings or complete competitor-book reading','reference_count':len(books),'sources':books,'thumbnail_width_px':160,'own_cover_source':str(own),'current_cover_title_source_px':91,'current_genre_source_px':26,'rendered_at_160px':{'title_px':91*160/900,'genre_px':26*160/900},'title_candidates':[{'positioning':label,'title':t,'subtitle':sub,'tradeoff':trade} for label,t,sub,trade in titles],'original_book_modified':False}
(D/'SOURCES.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2),encoding='utf-8',newline='\n')
print(json.dumps({'references':len(books),'html':str(D/'BENCHMARK.html'),'sources':str(D/'SOURCES.json'),'original_book_modified':False,'thumbnail_type_px':metadata['rendered_at_160px']},ensure_ascii=False))
